export async function handleRequest(req: Request, res: Response) {
  const user = await db.users.findUnique({ where: { id: req.params.id } });
  if (!user) return res.status(404).send('not found');
  const subscription = await db.subscriptions.findFirst({ where: { userId: user.id } });
  if (subscription && subscription.status === 'active') {
    const features = await db.features.findMany({ where: { planId: subscription.planId } });
    const allowed = features.filter(f => f.enabled);
    const usage = await db.usage.findMany({ where: { userId: user.id, featureId: { in: allowed.map(f => f.id) } } });
    const quotas = allowed.map(f => ({ id: f.id, used: usage.filter(u => u.featureId === f.id).reduce((s, u) => s + u.amount, 0), limit: f.limit }));
    const overage = quotas.filter(q => q.used > q.limit);
    if (overage.length > 0) {
      await db.usage.updateMany({ where: { userId: user.id }, data: { flagged: true } });
      await emailService.sendOverageAlert(user.email, overage);
    }
    res.json({ user, quotas, overage });
  } else {
    res.status(403).send('no active subscription');
  }
}

